// /frontend-react/src/components/TransportStatus.js

import React, { useState, useEffect } from 'react';
import { fetchDriverInfo } from '../utils/api'; 

// Mock user's specific need (this would come from App.js state or API in a real app)
const mockTransportNeed = 'wheelchair'; 

const NEED_EMOJIS = {
    wheelchair: { emoji: '♿', label: 'Wheelchair Access' },
    bedridden: { emoji: '🛏️', label: 'Stretcher Required' },
    slow: { emoji: '🚶', label: 'Slow Walking' },
};

function TransportStatus({ isEasyMode, goToMedicalDashboard, goToAppointmentFlow }) {
    const [driverInfo, setDriverInfo] = useState(null);

    useEffect(() => {
        const getData = async () => {
            const info = await fetchDriverInfo();
            setDriverInfo(info);
        };
        getData();
    }, []);

    if (!driverInfo) {
        return <h2 style={{fontSize: isEasyMode ? '48px' : '24px', textAlign: 'center'}}>Loading Transport Info...</h2>;
    }

    const currentNeed = NEED_EMOJIS[mockTransportNeed] || { emoji: '❓', label: 'Unknown Need' };

    return (
        <div style={{ padding: '20px', textAlign: 'center' }}>
            <h2 style={{fontSize: isEasyMode ? '48px' : '30px', margin: '10px'}}>Your Ride Status</h2>
            
            {/* 1. Display User's Transport Needs */}
            <div style={{ 
                margin: '20px 0', 
                padding: '15px', 
                border: '3px dashed #007bff', 
                borderRadius: '10px',
                backgroundColor: '#f0f8ff'
            }}>
                <p style={{fontSize: isEasyMode ? '36px' : '20px', fontWeight: 'bold'}}>
                    Your Booked Need:
                </p>
                <span role="img" aria-label={currentNeed.label} style={{fontSize: isEasyMode ? '80px' : '40px'}}>
                    {currentNeed.emoji}
                </span>
                <p style={{fontSize: isEasyMode ? '30px' : '18px', margin: '5px 0'}}>
                    {currentNeed.label}
                </p>
            </div>
            
            {/* 2. Driver Info */}
            <h3 style={{fontSize: isEasyMode ? '36px' : '24px', marginTop: '30px'}}>Driver Assigned</h3>
            <div style={{ display: 'flex', justifyContent: 'space-around', alignItems: 'center', border: '1px solid #ccc', padding: '15px', borderRadius: '10px' }}>
                
                {/* Driver Photo/Name */}
                <div style={{ textAlign: 'center' }}>
                    <span role="img" aria-label="Driver" style={{fontSize: isEasyMode ? '80px' : '40px', display: 'block'}}>🧑‍✈️</span>
                    <p style={{fontSize: isEasyMode ? '30px' : '18px', fontWeight: 'bold'}}>{driverInfo.name}</p>
                </div>

                {/* Car Details */}
                <div style={{ textAlign: 'left', fontSize: isEasyMode ? '24px' : '14px' }}>
                    <p>🚗 **{driverInfo.carType}**</p>
                    <p style={{ color: driverInfo.carColor.toLowerCase() }}>Color: **{driverInfo.carColor}**</p>
                    <p>Plate: **{driverInfo.licensePlate}**</p>
                </div>
            </div>

            {/* 3. Action Buttons */}
            <div style={{ marginTop: '30px' }}>
                 <button 
                    onClick={goToAppointmentFlow} // Use this to go back to the flow for editing
                    style={{ 
                        padding: '15px 30px', 
                        fontSize: isEasyMode ? '30px' : '18px',
                        backgroundColor: 'orange',
                        color: 'white',
                        border: 'none',
                        borderRadius: '10px',
                        marginRight: '15px'
                    }}
                >
                    <span role="img" aria-label="Edit">🔄</span> Change Need
                </button>
                
                <button 
                    onClick={goToMedicalDashboard} 
                    style={{ 
                        padding: '15px 30px', 
                        fontSize: isEasyMode ? '30px' : '18px',
                        backgroundColor: '#333',
                        color: 'white',
                        border: 'none',
                        borderRadius: '10px'
                    }}
                >
                    <span role="img" aria-label="Back">⬅️</span> Back to Medical Menu
                </button>
            </div>
        </div>
    );
}

// Mock utility function for the frontend
fetchDriverInfo = () => ({
    name: 'Sarah K.',
    carType: 'Blue Minivan',
    carColor: 'Blue',
    licensePlate: 'ABC 1234',
    // ... other mocked data ...
});

export default TransportStatus;
